import sys
from collections import deque

def min_cost_transform(c1, c2):
    d1 = abs(ord(c1) - ord(c2))
    d2 = 26 - d1
    return min(d1, d2)

def max_occurrences(S, T, K):
    N = len(S)
    M = len(T)

    dp = [[-1] * (K + 1) for _ in range(M + 1)]
    dp[0][0] = 0

    for i in range(1, M + 1):
        for j in range(K + 1):
            dp[i][j] = dp[i - 1][j]
            if j > 0:
                cost = min_cost_transform(T[i - 1], S[0])
                if cost <= j and dp[i - 1][j - cost] != -1:
                    dp[i][j] = max(dp[i][j], dp[i - 1][j - cost] + 1)

    for i in range(1, N):
        new_dp = [[-1] * (K + 1) for _ in	range(M + 1)]
        for j in range(i, M):
            for k in range(K + 1):
                new_dp[j][k] = new_dp[j - 1][k]
                if k > 0:
                    cost = min_cost_transform(T[j - 1], S[i])
                    if cost <= k and dp[j - 1][k - cost] != -1:
                        new_dp[j][k] = max(new_dp[j][k], dp[j - 1][k - cost] + 1)
        dp = new_dp

    max_occurrence = 0
    for j in range(K + 1):
        max_occurrence = max(max_occurrence, dp[M - 1][j])

    return max_occurrence

def main():
    import sys
    input = sys.stdin.read().split()
    N = int(input[0])
    M = int(input[1])
    K = int(input[2])
    S = input[3]
    T = input[4]
    print(max_occurrences(S, T, K))

if __name__ == "__main__":
    main()
